// Generated by kaitai-struct-compiler from maps/map.ksy, so it is not formatted or linted
#[path = "map_format.rs"]
#[allow(warnings, clippy::all)]
#[rustfmt::skip]
mod map_format;

use super::geom::{AABB, Position};
use crate::logging;
use kaitai::{BytesReader, KStruct};
use map_format::{MapFormat, MapFormat_MarkerType};

#[allow(dead_code)]
pub struct Map {
    pub all_aabbs: Vec<AABB>,
    pub wall_aabbs: Vec<AABB>,
    pub player_spawns: Vec<Position>,
    // Rectangles covering the floor, the hitboxes on it aren't subtracted
    pub floors: Vec<AABB>,
    // Area of the floors up to and including each one, to pick a random point on the floor
    floor_areas: Vec<u64>,
}

impl Map {
    pub fn from(map_ptr: *const u8, map_size: usize) -> Self {
        logging::info(&format!("starting map load from {map_ptr:?}"));
        let bytes = unsafe { std::slice::from_raw_parts(map_ptr, map_size) };
        let reader = BytesReader::from(bytes.to_vec());
        logging::debug(&format!("{map_size} bytes loaded"));
        let parsed =
            MapFormat::read_into::<_, MapFormat>(&reader, None, None).expect("map parse error");
        logging::info("map parsed successfully");

        let mut player_spawns = Vec::new();
        for m in parsed.markers().iter() {
            let pos = Position {
                x: *m.x() as i32,
                y: *m.y() as i32,
            };
            match *m.kind() {
                MapFormat_MarkerType::PlayerSpawn => player_spawns.push(pos),
                MapFormat_MarkerType::Unknown(id) => {
                    logging::warn(&format!("invalid marker kind {id}"));
                }
            }
        }

        let all_aabbs: Vec<AABB> = parsed
            .aabbs()
            .iter()
            .map(|a| AABB {
                pos: Position {
                    x: *a.x() as i32,
                    y: *a.y() as i32,
                },
                w: *a.w() as i32,
                h: *a.h() as i32,
            })
            .collect();
        let wall_aabbs: Vec<AABB> = parsed
            .aabbs()
            .iter()
            .filter(|a| *a.wall())
            .map(|a| AABB {
                pos: Position {
                    x: *a.x() as i32,
                    y: *a.y() as i32,
                },
                w: *a.w() as i32,
                h: *a.h() as i32,
            })
            .collect();

        let floors: Vec<AABB> = parsed
            .floors()
            .iter()
            .map(|f| AABB {
                pos: Position {
                    x: *f.x() as i32,
                    y: *f.y() as i32,
                },
                w: *f.w() as i32,
                h: *f.h() as i32,
            })
            .collect();
        logging::debug(&format!("loaded {} floor rectangles", floors.len()));
        let floor_areas = floors
            .iter()
            .scan(0, |total, f| {
                *total += (f.w * f.h) as u64;
                Some(*total)
            })
            .collect();

        Self {
            all_aabbs,
            wall_aabbs,
            player_spawns,
            floors,
            floor_areas,
        }
    }

    /// Returns a random point on the floor, with every pixel of floor equally likely, or None if
    /// the map has no floor
    pub fn random_floor_point(&self, rng: u64) -> Option<Position> {
        let total = *self.floor_areas.last()?;
        // The low bits of the LCG repeat quickly, so only the high ones are used
        let r = (rng >> 32) % total;
        // The first floor whose cumulative area goes past r, and the offset of r inside it
        let i = self.floor_areas.partition_point(|&area| area <= r);
        let offset = r - if i == 0 { 0 } else { self.floor_areas[i - 1] };
        let floor = &self.floors[i];
        Some(Position {
            x: floor.pos.x + (offset % floor.w as u64) as i32,
            y: floor.pos.y + (offset / floor.w as u64) as i32,
        })
    }

    /// Whether the AABB overlaps any of the hitboxes
    pub fn is_blocked(&self, aabb: &AABB) -> bool {
        self.all_aabbs.iter().any(|a| a.intersects(aabb))
    }

    pub fn random_player_spawn(&self, rng: u64) -> Position {
        self.player_spawns[rng as usize % self.player_spawns.len()]
    }
}
